#!/bin/zsh
# Generates the G-12 and G-06 art via Quiver Arrow 2 (two generations). Needs QUIVERAI_API_KEY exported in this shell.
cd /Users/emmanuel/Documents/Theory/TheOriginalPower || exit 1
S=.venv-voice/bin/scriptcast-video
$S svg generate 'Two identical semi-automatic AR-15 style rifles side by side, exact duplicates at the same scale, each with pistol grip, detachable box magazine, adjustable collapsible stock and handguard rail, pointing right, centered in a wide horizontal frame with a thin gap between them. No text, no logos, no brand marks, no people, no hands.' --instructions 'Flat two-tone vector, no gradients, no shadows, no background rectangle. Rifles filled solid cream #f4ead2 with small cutout details, transparent background. Wide composition about 950 by 330 pixels. Clean technical silhouette style, the two rifles must be perfectly identical.' --n 1
$S svg generate 'Abstract flat vector map motif of a 1930s redlining map: a grid of irregular city-block zones with thin street lines, zones coloured in four grades from safe to hazardous, with one cluster of hazardous zones highlighted. No text, no labels, no real place names, no logos, no people.' --instructions 'Flat vector, no gradients, no shadows, no background rectangle. Palette only: zone fills #6ec3c0 teal, #f4ead2 cream, #d9a441 gold, and #e2573f red for the hazardous cluster; street lines #16264a on top; transparent background. Wide composition about 950 by 330 pixels.' --n 1
